import base64,json,urllib.request
tok=[l.split("=",1)[1].strip() for l in open("/etc/vps-github-bridge/token") if l.startswith("GITHUB_TOKEN=")][0]
H={"Authorization":"token "+tok,"Accept":"application/vnd.github+json","User-Agent":"v"}
B="https://api.github.com/repos/ruslan591/weather-_Odessa/"
def api(path,data=None,method=None):
    req=urllib.request.Request(B+path,data=json.dumps(data).encode() if data is not None else None,headers=H,method=method)
    return json.load(urllib.request.urlopen(req,timeout=120))
main=api("git/ref/heads/main")["object"]["sha"]
try: print("ref",api("git/refs",{"ref":"refs/heads/exp-case-oct1","sha":main},"POST")["ref"])
except Exception as e: print("ref err",e)
d=base64.b64encode(open("/tmp/case_oct1.npz","rb").read()).decode()
r=api("contents/case_oct1.npz",{"message":"exp: frozen case 01.10 (temporary branch, not for main)","content":d,"branch":"exp-case-oct1"},"PUT")
print("uploaded",r["content"]["size"])
PYEOF
(nohup python3 /tmp/upcase.py > /tmp/upcase.log 2>&1 &); sleep 1; echo started
